public sealed class ValidationFilter<T>(IValidator<T> validator) : IEndpointFilter
{
    public async ValueTask<object?> InvokeAsync(
        EndpointFilterInvocationContext context, EndpointFilterDelegate next)
    {
        var arg = context.Arguments.OfType<T>().FirstOrDefault();
        if (arg is null)
            return Results.BadRequest(new ProblemDetails { Title = "Missing request body." });

        var result = await validator.ValidateAsync(arg, context.HttpContext.RequestAborted);
        if (!result.IsValid)
        {
            var errors = result.Errors.GroupBy(e => e.PropertyName)
                .ToDictionary(g => g.Key, g => g.Select(e => e.ErrorMessage).ToArray());
            return Results.ValidationProblem(errors);
        }
        return await next(context);
    }
}

var api = app.MapGroup("/api/products")
    .AddEndpointFilter<CorrelationIdFilter>()
    .AddEndpointFilter<ValidationFilter<CreateProductRequest>>()
    .RequireAuthorization();

api.MapPost("/", (CreateProductRequest req, ProductService svc) =>
    Results.Created($"/api/products/1", req));

api.MapGet("/{id:int}", (int id, ProductService svc) =>
    Results.Ok(svc.Get(id)));

public sealed class DataAnnotationsFilter<T> : IEndpointFilter
{
    public ValueTask<object?> InvokeAsync(
        EndpointFilterInvocationContext context, EndpointFilterDelegate next)
    {
        var model = context.Arguments.OfType<T>().FirstOrDefault();
        if (model is null) return ValueTask.FromResult<object?>(Results.BadRequest());

        var results = new List<ValidationResult>();
        var ctx = new ValidationContext(model);
        if (!Validator.TryValidateObject(model, ctx, results, true))
        {
            var errors = results.ToDictionary(
                r => r.MemberNames.FirstOrDefault() ?? string.Empty,
                r => new[] { r.ErrorMessage ?? "Invalid." });
            return ValueTask.FromResult<object?>(Results.ValidationProblem(errors));
        }
        return next(context);
    }
}

